window.products.push({"id":530681,"name":"Wilton Decorating Bag Holder","category":"homeandappliances","retail price":39.11,"sale price":null,"image":"https://m.media-amazon.com/images/I/81pqUjy-4zL._AC_SL1500_.jpg","description":"Saves decorating space and time! Keep your icing bags close at hand and organize your decorating space with this convenient stand. Great for Wilton Featherweight, Disposable or Parchment Bags! The 2 large and 6 small spaces hold bags upright so they’ll be easy to grab. Use the smallest openings to hold flower and cupcake nails. To prevent air from drying out icing, we suggest using Wilton Tip Covers or placing a damp towel that touches tip ends under the Bag Holder.","images":["https://m.media-amazon.com/images/I/81pqUjy-4zL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Wilton","source_asin":"B00FB58RWC","category_path":"Home & Kitchen"},"sku":"BM-530681","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00FB58RWC","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00FB58RWC","price_pending":true,"merchant_ready":false});
